/* cppi::fde10069ff341128c5fca786484025bb4cb6bb0f576d22e5ede3916e3604555a */
SELECT * FROM (SELECT *
FROM (
  SELECT business_date, value FROM "tfm_prod"."bp_analytics" where portfolio = 'acpp_current_core_current'  and analytic = 'EDR_AVG'
) "custom_sql_query"
LIMIT 0) T LIMIT 0

/* cppi::0ef1e2128b680391c17cd59189cfee25a996c19b215bf28477c5f5081f7a7e23 */
/* QuickSight */
SELECT ds.* FROM ( WITH country_max AS (
    SELECT MAX(end_date) as max_end_date
    FROM alternative_assets_dev.listed_real_assets_bloomberg_attribution_by_country
),
sector_max AS (
    SELECT MAX(end_date) as max_end_date
    FROM alternative_assets_dev.listed_real_assets_bloomberg_attribution_by_sector
)
SELECT LEAST(country_max.max_end_date, sector_max.max_end_date) as older_max_date
FROM country_max, sector_max ) ds LIMIT 0

/* cppi::0ef1e2128b680391c17cd59189cfee25a996c19b215bf28477c5f5081f7a7e23 */
